async function ensureChapter(key){if(loadedChapters.has(key))return;if(!CHAPTERS[key])throw Error('没有这个章节');if(chapterLoads.has(key))return chapterLoads.get(key);const p=(async()=>{let error;for(let retry=0;retry<2;retry++){try{await new Promise((resolve,reject)=>{const s=document.createElement('script');let done=false;const finish=(err)=>{if(done)return;done=true;clearTimeout(timer);if(err){s.remove();reject(err)}else resolve()};const timer=setTimeout(()=>finish(Error('题库加载超时')),12000);s.src='q_'+key+'.js?v='+window.MB_VER+(retry?'&retry=1':'');s.onload=()=>finish();s.onerror=()=>finish(Error('题库暂不可用，请检查网络或离线资源'));document.head.append(s)});const list=CHAPTERS[key];if(list.some(q=>!window.QDATA?.[q.q]))throw Error('章节题目不完整，原学习记录已保留');for(const q of list){const full=window.QDATA[q.q];Object.assign(q,full,{_key:key,kp:clean(full.kp)});}loadedChapters.add(key);return}catch(e){error=e}}throw error})().finally(()=>chapterLoads.delete(key));chapterLoads.set(key,p);return p;}
