function toCoreExam(x,graded){const old=exams.find(e=>e.id===x.id)||{},ans={},notes={};for(const[id,r]of Object.entries(x.answers||{})){if(byId.get(id)?.t==='calc'){notes[id]=String(r.answer||'');ans[id]=r.correct===null?'':r.correct?'ok':'no'}else ans[id]=String(r.answer||'')};const weights=x.weights||Object.fromEntries(x.ids.map(id=>[id,pointsFor(byId.get(id))]));return {...old,id:x.id||'E'+Date.now(),tk:x.subject,ts:x.start||x.time||Date.now(),updatedAt:Date.now(),sub:META[x.subject].name,qids:x.ids.slice(),ans,notes,score:x.score||0,right:x.correct||0,pending:x.pending||0,total:x.total||x.ids.reduce((n,id)=>n+(weights[id]||4),0),graded,weights,minutes:x.minutes||0,deadline:x.deadline||0,timedOut:x.timedOut===true,endedAt:x.endedAt||0,elapsedMs:x.elapsedMs||0,answerTimes:x.answerTimes||{},timeNotified:x.timeNotified===true,mode:x.mode||'official'};}
