 const wanted=new Set(state.fav),prior=new Set(baselineFav),live=new Set(fav);let favChanged=false;for(const id of new Set([...wanted,...prior]))if(wanted.has(id)!==prior.has(id)){if(wanted.has(id))live.add(id);else live.delete(id);favOps[id]={on:wanted.has(id),t:Math.max(now,(favOps[id]?.t||0)+1)};favChanged=true;}if(favChanged){fav=[...live];_favLocalT=now;dirty=true}
