function courseResults(term){term=term.trim().toLowerCase();if(!term)return `<div class="course-grid">${Object.entries(META).map(([k,v])=>`<button class="course-card" data-act="course" data-k="${k}"><div class="row">${subjectIcon(k)}<div><h3>${v.name}</h3><p class="meta">${v.chapters.length} 个章节 · ${nTotal(k).toLocaleString()} 道题</p></div></div>${icon('chevron','arrow')}<div class="course-bottom"><span>日常已练 ${countDone(k)} 题</span><span class="desktop-only">查看章节</span><span class="mobile-only">${Math.round(countDone(k)/nTotal(k)*100)}%</span></div>${progress(countDone(k),nTotal(k))}</button>`).join('')}</div>`;
const chapters=[];for(const[k,v]of Object.entries(META))v.chapters.forEach((c,i)=>{if((v.name+c.name+c.kps.map(p=>clean(p.name)).join(' ')).toLowerCase().includes(term))chapters.push([k,c,i])});const qs=allQ.filter(q=>q.s&&!isImage(q.s)&&(strip(q.s)+q.tk).toLowerCase().includes(term)).slice(0,10);return `<div class="inline-note">首页显示部分匹配结果。<a class="text-btn" href="#search">打开完整搜索与筛选</a></div><div class="search-results">${chapters.slice(0,20).map(([k,c,i])=>chapterRow(k,c,i)).join('')}${qs.map(q=>`<button class="chapter-row" data-act="open-q" data-id="${q.q}">${icon('search')}<span class="chapter-copy"><strong>${esc(strip(q.s).slice(0,75))}</strong><p>${META[q.tk].name} · ${esc(clean(q.kp))}</p></span>${icon('chevron')}</button>`).join('')}${!chapters.length&&!qs.length?empty('没有找到相关内容','试试“极限”“导数”或“C语言”等关键词。','清除搜索','clear-search'):''}</div>`}
function chapterRow(k,c,i){const arr=CHAPTERS[`${k}_${i}`],done=arr.filter(q=>state.rec[q.q]).length,right=arr.filter(q=>state.rec[q.q]?.correct).length,stable=c.kps.filter(p=>{const answered=arr.filter(q=>q.kpid===p.id&&state.rec[q.q]);return answered.length>=5&&answered.filter(q=>state.rec[q.q].correct).length/answered.length>=.8}).length;return `<button class="chapter-row" data-act="chapter" data-key="${k}_${i}"><span class="chapter-number">${String(i+1).padStart(2,'0')}</span><span class="chapter-copy"><strong>${esc(c.name)}</strong><p>${c.kps.length} 个知识点 · 已完成 ${done} 题 · 当前正确率 ${done?Math.round(right/done*100)+'%':'—'}${done<5?'（样本不足）':''}</p><p>${stable} 个知识点较稳定 · ${c.kps.filter(p=>p.n>0).length-stable} 个待巩固</p></span><span class="chapter-count">${c.total} 题</span>${icon('chevron')}</button>`}
function course(k){if(!META[k])return home();const v=META[k],done=countDone(k);return `${heading(v.name,`${v.chapters.length} 个章节 · ${nTotal(k).toLocaleString()} 道题 · 选择章节开始练习`)}<section class="panel"><div class="between"><strong>日常练习完成度</strong><span>${done} / ${nTotal(k)} · ${Math.round(done/nTotal(k)*100)}%</span></div>${progress(done,nTotal(k))}</section><div class="chapter-list space-top">${v.chapters.map((c,i)=>chapterRow(k,c,i)).join('')}</div>${footer()}`}


let favoriteMode=false,favoriteScope=null;
function favoriteQuestions(subject,chapter='',kp=''){
 const ids=new Set(state.fav);return allQ.filter(q=>ids.has(q.q)&&q.tk===subject&&(!chapter||q._key===subject+'_'+chapter)&&(!kp||q.kpid===kp));
}
function favoriteBase(){return favoriteScope?favoriteQuestions(favoriteScope.subject,favoriteScope.chapter,favoriteScope.kp):[]}
function favoriteRun(subject,chapter='',kp=''){return 'favorites/run/'+subject+(chapter!==''?'/'+chapter:'')+(kp?'/'+kp:'')}
function favoriteLink(route,label,count){return `<a class="chapter-row" href="#${route}"><span class="chapter-copy"><strong>${esc(label)}</strong></span><span class="chapter-count">${count} 道收藏</span>${icon('chevron')}</a>`}
function favoriteTabs(){return `<div class="tabs" aria-label="复习分类"><button data-act="review-tab" data-value="wrong">错题本 ${wrongIds().length}</button><a class="active" href="#favorites" aria-current="page">我的收藏 ${state.fav.length}</a></div>`}
function favoriteChapter(subject,c,i){const arr=favoriteQuestions(subject,String(i));return `<details class="favorite-chapter"><summary><span>${esc(c.name)}</span><span class="chapter-count">${arr.length} 道收藏</span></summary><div class="kp-list">${arr.length?favoriteLink(favoriteRun(subject,String(i)),'练习本章全部收藏',arr.length):'<p class="muted small">本章暂无收藏题目</p>'}${c.kps.map(p=>{const n=arr.filter(q=>q.kpid===p.id).length;return n?favoriteLink(favoriteRun(subject,String(i),p.id),clean(p.name),n):''}).join('')}</div></details>`}
function favoriteCatalogue(subject=''){
 const unmatched=state.fav.filter(id=>!byId.has(id)).length;
 if(subject&&!META[subject])return favoriteCatalogue();
 return `${heading(subject?META[subject].name+' · 收藏':'我的收藏',subject?'按大章节或知识点集中复习，也可以练习本科目全部收藏。':'选择科目，再按章节与知识点复习收藏题。')}${favoriteTabs()}${unmatched?`<div class="inline-note">有 ${unmatched} 条旧收藏暂未匹配，编号仍保留在备份中。</div>`:''}${subject?`<div class="favorite-actions"><a class="btn" href="#favorites">${icon('back')}全部科目</a>${favoriteQuestions(subject).length?`<a class="btn primary" href="#${favoriteRun(subject)}">练习本科目全部收藏 ${icon('arrow')}</a>`:''}</div><div class="chapter-list">${META[subject].chapters.map((c,i)=>favoriteChapter(subject,c,i)).join('')}</div>`:`<div class="course-grid">${Object.entries(META).map(([k,v])=>{const arr=favoriteQuestions(k),done=arr.filter(q=>state.rec[q.q]).length;return `<a class="course-card" href="#favorites/course/${k}"><div class="row">${subjectIcon(k)}<div><h3>${v.name}</h3><p class="meta">${arr.length} 道收藏 · ${new Set(arr.map(q=>q._key)).size} 个章节</p></div></div>${icon('chevron','arrow')}<div class="course-bottom"><span>已作答 ${done} / ${arr.length}</span><span>查看收藏章节</span></div>${arr.length?progress(done,arr.length):'<p class="muted small">暂无收藏，可在题目上点击星标添加</p>'}</a>`}).join('')}</div>`}${footer()}`;
}
function favoriteTitle(){const {subject,chapter,kp}=favoriteScope;if(kp)return clean(META[subject].chapters[chapter].kps.find(p=>p.id===kp)?.name);return chapter!==''?META[subject].chapters[chapter].name:META[subject].name+'全部收藏'}
function rememberFavorite(q){if(!favoriteMode||!q)return;state.favoriteLast[favoriteScope.key]=q.q;persistUI()}
function enterFavoriteScope(route){
 const parts=route.split('/'),subject=parts[2],chapter=parts[3]??'',kp=parts[4]||'';
 if(!META[subject]||(chapter!==''&&!META[subject].chapters[chapter])||(kp&&!META[subject].chapters[chapter]?.kps.some(p=>p.id===kp))||parts.length>5)throw Error('收藏范围无效，请返回收藏目录');
 favoriteScope={subject,chapter,kp,key:route};chapterKey=subject+'_'+(chapter||'0');examRun=false;filter='all';learning='practice';layout=state.favoriteLayout;
 const arr=favoriteBase(),saved=state.favoriteLast[route];position=arr.findIndex(q=>q.q===saved);
 if(position<0){let latest=-1;position=0;arr.forEach((q,i)=>{if(rec[q.q]&&recordTime(rec[q.q])>latest){position=i;latest=recordTime(rec[q.q])}})}
 limit=Math.max(20,Math.ceil((position+1)/20)*20);
}
function favoriteDirectory(){const s=favoriteScope;modal('收藏目录',`<div class="favorite-actions"><a class="btn" href="#favorites">全部科目</a><a class="btn" href="#favorites/course/${s.subject}">${META[s.subject].name}收藏</a></div>${favoriteLink(favoriteRun(s.subject),'本科目全部收藏',favoriteQuestions(s.subject).length)}<div class="scope-list">${META[s.subject].chapters.map((c,i)=>favoriteChapter(s.subject,c,i)).join('')}</div>`,{drawer:true})}

function pool(){if(examRun)return(state.draft?.ids||[]).map(id=>byId.get(id)).filter(Boolean);return(favoriteMode?favoriteBase():(CHAPTERS[chapterKey]||[])).filter(q=>filter==='all'||filter==='new'&&!state.rec[q.q]||filter==='wrong'&&state.rec[q.q]&&!state.rec[q.q].correct||filter==='fav'&&state.fav.includes(q.q)||filter.startsWith('kp:')&&q.kpid===filter.slice(3))}
function answeredCount(d){return Object.values(d?.answers||{}).filter(r=>typeof r.answer==='string'&&r.answer.trim()).length}
function answerRecord(q){const r=examRun?state.draft.answers[q.q]:retrying.has(q.q)?undefined:state.rec[q.q];return examRun&&!r?.answer?.trim()?undefined:r}
function practice(){const arr=pool(),[k,c]=chapterKey.split('_'),ch=META[k]?.chapters[c];if(!ch&&!examRun)return home();position=Math.max(0,Math.min(position,arr.length-1));const scope=favoriteMode?favoriteBase():CHAPTERS[chapterKey]||[],scopeTotal=scope.length;const q=arr[position],done=scope.filter(q=>state.rec[q.q]).length,shown=layout==='list'?arr.slice(0,limit):q?[q]:[];return `<div class="practice-heading"><div><h1>${examRun?(state.draft.mode==='official'?'官方模拟':'专项练习'):favoriteMode?esc(favoriteTitle()):esc(ch.name.replace(/^第\d+章\s*/,''))}</h1><p>${examRun?`${META[state.draft.subject].name} · 已答 ${answeredCount(state.draft)} / ${arr.length} 题`:esc(META[k].name)+(favoriteMode?' · 当前范围 '+scopeTotal+' 道收藏':' · 全章 '+ch.total+' 题')}</p></div><button class="btn" data-act="${examRun?'card':'directory'}">${icon(examRun?'grid':'menu')}${examRun?'答题卡':'目录'}</button></div><div class="practice-controls"><div class="practice-tools"><button class="btn" style="${examRun?'display:none':''}" data-act="${examRun?'card':'directory'}">${icon('menu')}${examRun?'答题卡':'目录'}</button><button class="btn" data-act="card">${icon('grid')}答题卡</button></div><div class="row">${!examRun?`<div class="segment" aria-label="学习模式"><button data-act="learning" data-value="practice" class="${learning==='practice'?'active':''}" aria-pressed="${learning==='practice'}">练习模式</button><button data-act="learning" data-value="memorize" class="${learning==='memorize'?'active':''}" aria-pressed="${learning==='memorize'}">背题模式</button></div>`:`<span class="pill">${state.draft.minutes?'限时 '+state.draft.minutes+' 分钟':'不限时'} · <span data-exam-clock>${examElapsed()}</span></span>`}<div class="segment" aria-label="显示方式"><button data-act="layout" data-value="single" class="${layout==='single'?'active':''}" aria-pressed="${layout==='single'}">单题</button><button data-act="layout" data-value="list" class="${layout==='list'?'active':''}" aria-pressed="${layout==='list'}">列表</button></div><button class="icon-btn" data-act="more" aria-label="更多操作">${icon('more')}</button></div>${!examRun?`<div class="filter-row" aria-label="题目范围"><span class="filter-label">范围</span>${(favoriteMode?[['all','全部收藏'],['new','未做'],['wrong','错题']]:[['all','全部'],['new','未做'],['wrong','错题'],['fav','收藏']]).map(([a,b])=>`<button class="filter-chip ${filter===a?'active':''}" data-act="filter" data-value="${a}" aria-pressed="${filter===a}">${b}</button>`).join('')}${filter!=='all'?`<button class="text-btn" data-act="filter" data-value="all">清除筛选</button>`:''}</div>`:''}</div>${filter.startsWith('kp:')?`<div class="inline-note">知识点：${esc(clean(arr[0]?.kp||'此知识点暂无题目'))}</div>`:''}<div class="question-layout"><div>${layout==='list'?`<p class="list-hint">分批展示：已加载 ${shown.length} / ${arr.length} 题</p>`:''}${shown.length?shown.map(q=>questionCard(q,arr.indexOf(q),arr.length)).join(''):favoriteMode?empty('当前范围暂无可复习的收藏','可以调整筛选，或返回收藏目录选择其他章节。','返回收藏目录','favorite-catalogue'):empty('这个范围里暂时没有题目',filter==='fav'?'点击题目右上角的星标，即可加入收藏。':'可以切换到全部题目，或选择其他知识点。','查看全部题目','all-questions')}${layout==='list'&&limit<arr.length?`<div class="load-more"><button class="btn" data-act="load-more">再加载 20 题 ${icon('arrow')}</button></div>`:''}<div class="question-pager"><button class="btn" data-act="prev" ${position<=0||!arr.length?'disabled':''}>${icon('back')}上一题</button><button class="btn pager-card" data-act="card" aria-label="打开答题卡">${icon('grid')}<span class="desktop-only">答题卡</span></button><button class="btn primary" data-act="${examRun&&position===arr.length-1?'finish':'next'}" ${(!arr.length||position>=arr.length-1)&&!examRun?'disabled':''}>${examRun&&position===arr.length-1?'提交练习':'下一题'}${icon('arrow')}</button></div>${footer()}</div><aside class="practice-aside"><div class="panel"><h3>${examRun?'本次练习':favoriteMode?'收藏进度':'章节进度'}</h3><div class="aside-progress"><div class="between"><span>已完成 ${examRun?answeredCount(state.draft):done} 题</span><span>${examRun?arr.length:scopeTotal} 题</span></div>${progress(examRun?answeredCount(state.draft):done,examRun?arr.length:scopeTotal)}</div><div class="legend"><span><i class="done"></i>正确</span><span><i class="wrong"></i>待复习</span></div><div class="number-grid">${numberButtons(arr.slice(0,16))}</div><div class="aside-links"><button data-act="card">完整答题卡 ${icon('chevron')}</button><button data-act="${examRun?'finish':'directory'}">${examRun?'提交本次练习':'章节与知识点'} ${icon('chevron')}</button><button data-act="more">练习设置 ${icon('settings')}</button></div></div><p class="muted small" style="margin:16px 6px">${examRun?'离开页面时自动保留本次练习。':favoriteMode?`当前范围共 ${scopeTotal} 道收藏，作答先保存到本机。`:`本章共 ${CHAPTERS[chapterKey].length} 道题，作答先保存到本机。`}</p></aside></div>`}
function isImage(v){return typeof v==='string'&&v.startsWith('img/')}
function strip(v){const d=document.createElement('div');d.innerHTML=String(v||'');return d.textContent||''}
function safeHTML(v){const t=document.createElement('template');t.innerHTML=String(v||'');t.content.querySelectorAll('*').forEach(e=>{if(!['DIV','SPAN','P','BR','B','STRONG','EM','I','U','SUB','SUP','UL','OL','LI','H4','H3','TABLE','TR','TD','TH','TBODY','THEAD','PRE','CODE'].includes(e.tagName)){e.replaceWith(document.createTextNode(e.textContent));return}for(const a of [...e.attributes])if(a.name!=='class')e.removeAttribute(a.name)});return t.innerHTML}
function content(v,alt,allowHTML=false,zoom=true){if(isImage(v)){const img=`<img src="${esc(v)}" alt="${esc(alt)}" loading="lazy">`;return zoom?`<span class="image-wrap"><button class="image-btn" data-act="zoom" data-img="${esc(v)}" aria-label="放大${esc(alt)}">${img}</button></span>`:img}return allowHTML?safeHTML(v):esc(v).replace(/\n/g,'<br>')}

function questionCard(q,idx,total){const r=answerRecord(q),isReveal=(!examRun&&(learning==='memorize'||r||openedAnswers.has(q.q))),selections=multiSelections[q.q]||(q.t==='multi'&&r?.answer?[...r.answer]:[]);let opts='';if(q.t==='calc'&&examRun){opts=`<div class="inline-note">在纸上完成计算，可在下方记下结果。交卷后对照解析自评。</div><textarea class="calc-entry" id="calc-${q.q}" aria-label="计算题作答记录" placeholder="记录你的结果或思路（可选）">${esc(r?.answer||'')}</textarea><button class="btn primary" data-act="calc-save" data-id="${q.q}">${r?'更新作答':'标记已完成'}</button>`}else if(q.t==='calc'){opts=`<div class="inline-note">先在纸上计算，查看解析后自评。</div>${isReveal?`<div class="row"><button class="btn soft" data-act="self" data-id="${q.q}" data-value="ok">${icon('check')}答对了</button><button class="btn" data-act="self" data-id="${q.q}" data-value="no">还需练习</button></div>`:`<button class="btn" data-act="reveal" data-id="${q.q}">查看参考解答</button>`}`}
else if(q.t==='blank'){opts=`<div class="blank-entry"><input id="blank-${q.q}" aria-label="本题答案" placeholder="输入答案" value="${esc(r?.answer||'')}"><button class="btn primary" data-act="blank" data-id="${q.q}">${examRun?'保存答案':'核对答案'}</button></div>`}
else{opts=`<div class="options">${Object.entries(q.o||{}).map(([n,v])=>{const letter=String.fromCharCode(64+Number(n)),chosen=q.t==='multi'?selections.includes(letter):r?.answer===letter;const cls=isReveal&&q.a.includes(letter)?'correct':isReveal&&chosen&&!r?.correct?'wrong':chosen?'selected':'';return `<button class="option ${cls}" data-act="answer" data-id="${q.q}" data-letter="${letter}" aria-pressed="${chosen||false}"><span class="letter">${letter}</span><span class="option-content">${content(v,'选项 '+letter,false,false)}</span>${isReveal&&q.a.includes(letter)?icon('check'):''}</button>`}).join('')}</div>${q.t==='multi'?`<div class="row space-top"><button class="btn primary" data-act="multi" data-id="${q.q}">${examRun?'保存选择':'确认作答'}</button><span class="muted small">多选题，请选择全部正确选项</span></div>`:''}`}
return `<article class="question-card" id="q-${q.q}"><div class="q-top"><span class="q-number">${String(idx+1).padStart(2,'0')} <span class="muted">/ ${total}</span></span>${badge(typeName(q))}<span class="q-kp">${esc(clean(q.kp))}</span><button class="icon-btn ${state.fav.includes(q.q)?'on':''}" data-act="favorite" data-id="${q.q}" aria-label="${state.fav.includes(q.q)?'取消收藏':'收藏本题'}" aria-pressed="${state.fav.includes(q.q)}">${icon('star')}</button></div><div class="stem">${content(q.s,'题干',q.t==='calc')}</div>${opts}${isReveal?`<section class="answer-result"><strong class="${r&&!r.correct?'wrong-text':'correct-text'}">${q.t==='calc'?'参考解答与自评':r?(r.correct?'回答正确':'再巩固一下'):'背题模式 · 参考答案'}${q.t!=='calc'?' · '+esc(q.a):''}</strong>${r&&!r.correct&&q.t!=='calc'?`<p class="muted">你的答案：${esc(r.answer)}</p>`:''}<div class="explanation">${q.eh?safeHTML(q.eh):q.et?esc(q.et).replace(/\n/g,'<br>'):q.w?content(q.w,'答案解析'): '原题未提供详细解析，可对照参考答案复习。'}</div></section>`:''}<div class="q-footer"><button class="text-btn" data-learning="feedback" data-id="${q.q}">题目纠错</button>${!examRun?`<button class="text-btn" data-learning="retry" data-id="${q.q}">再练一次</button>`:''}<span>${examRun?r?'答案已暂存':'提交后统一查看答案':r?'本题作答已保存':'作答后自动保存'}</span>${isImage(q.s)?`<button class="text-btn" data-act="zoom-question" data-id="${q.q}">${icon('zoom')}放大题图</button>`:`<span>${esc(META[q.tk].name)}</span>`}</div></article>`}
function numberButtons(arr){return arr.map((q,i)=>{const r=answerRecord(q),pending=examRun&&q.t==='calc'&&r?.correct==null&&r?.answer,className=examRun?(pending?'pending':r?'answered':''):(r?(r.correct?'done':'wrong'):'');return `<button data-act="jump" data-id="${q.q}" class="${className} ${pool()[position]?.q===q.q?'current':''}" aria-label="第 ${i+1} 题 · ${pending?'待自评':r?(examRun?'已作答':r.correct?'已答正确':'已答错误'):'未作答'}" ${pool()[position]?.q===q.q?'aria-current="true"':''}>${i+1}</button>`}).join('')}
function empty(title,desc,label,act){return `<section class="empty">${subjectIcon('GS')}<h3>${title}</h3><p>${desc}</p><button class="btn primary" data-act="${act}">${label} ${icon('arrow')}</button></section>`}
function review(){if(reviewTab==='fav')return favoriteCatalogue();return '<div class="inline-note between"><span>错题本与收藏照常保留；到期任务可在智能复习查看。</span><a class="btn soft" href="#smart-review">智能复习</a></div>'+baseReview()}
function baseReview(){const ids=(reviewTab==='wrong'?wrongIds():state.fav).filter(id=>byId.has(id)&&(reviewSubject==='all'||byId.get(id).tk===reviewSubject));return `${heading('把会的记牢，把错的弄懂','错题与收藏集中管理，复习从这里开始。')}<div class="review-summary"><div class="panel"><span>待复习错题</span><strong>${wrongIds().length}</strong></div><div class="panel"><span>已收藏题目</span><strong>${state.fav.length}</strong></div><div class="panel"><span>累计练习</span><strong>${Object.keys(state.rec).length}</strong></div></div><div class="tabs" aria-label="复习分类"><button data-act="review-tab" data-value="wrong" class="${reviewTab==='wrong'?'active':''}">错题本 ${wrongIds().length}</button><button data-act="review-tab" data-value="fav" class="${reviewTab==='fav'?'active':''}">我的收藏 ${state.fav.length}</button></div><div class="between" style="margin-bottom:18px"><div class="filter-row">${[['all','全部'],...Object.entries(META).map(([k,v])=>[k,v.name])].map(([k,n])=>`<button data-act="review-subject" data-value="${k}" class="filter-chip ${reviewSubject===k?'active':''}">${n}</button>`).join('')}</div></div>${ids.length?ids.slice(0,reviewLimit).map(id=>{const q=byId.get(id);return `<button class="review-card" data-act="open-q" data-id="${id}">${subjectIcon(q.tk)}<span style="flex:1;min-width:0"><span class="meta">${META[q.tk].name} · ${esc(clean(q.kp))}</span><div class="snippet">${content(q.s,'题干',false,false)}</div><span class="meta">${reviewTab==='wrong'?'上次未答对 · 点击重新练习':'已收藏 · 点击查看题目'}</span></span>${icon('chevron')}</button>`}).join(''):empty(reviewTab==='wrong'?'这里暂时没有错题':'收藏夹还是空的',reviewTab==='wrong'?'继续练习，错题会自动整理到这里。':'遇到值得再看的题，点击星标就能收藏。','去题库选题','home')}${ids.length>reviewLimit?'<div class="load-more"><button class="btn" data-act="review-more">加载更多复习题</button></div>':''}${footer()}`}
function eligible(){return Object.values(CHAPTERS).flat().filter(q=>q.tk===examSubject&&selected.has(q.kpid))}

initScope('GS');



function examElapsed(){if(!state.draft)return '';const t=LearningCore.timer(state.draft),format=ms=>String(Math.floor(ms/60000)).padStart(2,'0')+':'+String(Math.floor(ms/1000)%60).padStart(2,'0');return t.timedOut?'已超时 · 仍可继续作答 · 已用 '+format(t.elapsed):t.remaining==null?'已用 '+format(t.elapsed):'剩余 '+format(t.remaining)}



function modal(title,body,{drawer=false,image=false}={}){const d=$('#dialog');if(d.open)d.close();d.className=drawer?'drawer':image?'image-dialog':'';d.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="icon-btn" data-act="close" aria-label="关闭弹窗">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;d.showModal();typeset(d)}
function close(){if($('#dialog').open)$('#dialog').close()}
function directory(){if(favoriteMode)return favoriteDirectory();const[k,c]=chapterKey.split('_'),ch=META[k].chapters[c],arr=CHAPTERS[chapterKey];modal('目录',`<div class="eyebrow">${META[k].name}</div><h3>${esc(ch.name)}</h3><p class="muted small" style="margin:7px 0 20px">全章 ${ch.total} 题 · ${ch.kps.length} 个知识点</p><div class="scope-list"><details open><summary>${icon('chevron')}本章知识点</summary><div class="kp-list">${ch.kps.map(p=>{const available=arr.some(q=>q.kpid===p.id);return `<button class="chapter-row" data-act="kp" data-value="${p.id}" ${!available?'disabled':''} style="margin-top:8px"><span class="chapter-copy"><strong>${esc(clean(p.name))}</strong>${!available?'<p>此知识点暂时没有题目</p>':''}</span><span class="chapter-count">${p.n} 题</span></button>`}).join('')}</div></details><details><summary>${icon('chevron')}切换章节 <small>${META[k].chapters.length} 章</small></summary><div class="kp-list">${META[k].chapters.map((c,i)=>chapterRow(k,c,i)).join('')}</div></details></div>`,{drawer:true})}
function card(){const arr=pool();modal('答题卡',`<div class="between"><p class="muted small">${arr.length} 题 · 点击题号跳转 · 外框为当前题</p>${examRun?'<button class="text-btn" data-act="finish">提交练习</button>':''}</div><div class="legend"><span><i class="done"></i>${examRun?'已作答（交卷后判分）':'已答正确'}</span>${examRun?'<span><i class="pending"></i>待自评</span>':'<span><i class="wrong"></i>已答错误</span>'}<span><i></i>未作答</span></div><div class="number-grid">${numberButtons(arr)}</div>`,{drawer:true})}


function move(n){const arr=pool();position=Math.max(0,Math.min(arr.length-1,position+n));if(favoriteMode)rememberFavorite(arr[position]);if(!examRun&&!favoriteMode&&arr[position]){rememberLast(chapterKey,CHAPTERS[chapterKey].indexOf(arr[position]));save()}if(layout==='list'){limit=Math.max(limit,Math.ceil((position+1)/20)*20);render();$('#q-'+arr[position]?.q)?.scrollIntoView({block:'start'})}else{render();window.scrollTo(0,0)}}



function finish(){if(!state.draft)return;const unanswered=state.draft.ids.length-answeredCount(state.draft);modal('提交这次练习？',`<p>${unanswered?'还有 '+unanswered+' 道题未作答。提交后可查看结果和参考答案。':'所有题目已作答，提交后可查看结果。'}</p><div class="dialog-actions"><button class="btn" data-act="close">继续作答</button><button class="btn primary" data-act="confirm-finish">提交并查看</button></div>`)}


function zoom(img){zoomScale=1;modal('题图原件',`<div class="zoom-tools"><button class="btn" data-act="zoom-out" aria-label="缩小题图">−</button><span id="zoom-label">100%</span><button class="btn" data-act="zoom-in" aria-label="放大题图">＋</button><span class="muted small">放大后可横向滚动</span></div><div class="zoom-viewport"><img id="zoom-image" src="${esc(img)}" alt="原始题图放大预览"></div>`,{image:true});const im=$('#zoom-image');im.onload=()=>{im.dataset.original=im.naturalWidth;im.style.width=im.naturalWidth+'px'};if(im.complete){im.dataset.original=im.naturalWidth;im.style.width=im.naturalWidth+'px'}}





document.addEventListener('click',e=>{const b=e.target.closest('[data-act]');if(!b||b.disabled)return;const a=b.dataset.act,id=b.dataset.id,q=byId.get(id);switch(a){
case'favorite-catalogue':go('favorites/course/'+favoriteScope.subject);break;case'about':about();break;case'close':close();break;case'home':close();go('home');break;case'course':go('course/'+b.dataset.k);break;case'chapter':close();enterChapter(b.dataset.key);break;case'continue':enterChapter(state.last.key,state.last.index);break;case'open-q':close();openQuestion(id);break;case'back-practice':if(favoriteMode){go('favorites/course/'+favoriteScope.subject);break}go(examRun?'exam':previousRoute.startsWith('practice')?'course/'+chapterKey.split('_')[0]:previousRoute);break;
case'review':reviewTab=b.dataset.tab;reviewSubject='all';go(reviewTab==='fav'?'favorites':'review');break;case'review-tab':reviewTab=b.dataset.value;go(reviewTab==='fav'?'favorites':'review');break;case'review-subject':reviewSubject=b.dataset.value;render();break;case'clear-search':searchTerm='';render();break;
case'learning':learning=b.dataset.value;render();break;case'layout':layout=b.dataset.value;if(favoriteMode){state.favoriteLayout=layout;persistUI()}render();break;case'filter':filter=b.dataset.value;position=0;limit=20;rememberCurrent();save();render();break;case'all-questions':filter='all';position=0;rememberCurrent();save();render();break;case'load-more':{const y=scrollY;limit+=20;render();window.scrollTo(0,y);break}
case'favorite':if(q){clearTimeout(autoTimer);const before=favoriteMode?pool():[];const current=before[position]?.q;state.fav=state.fav.includes(id)?state.fav.filter(v=>v!==id):[...state.fav,id];save();if(favoriteMode){const arr=pool(),at=arr.findIndex(q=>q.q===current);position=at>=0?at:Math.max(0,Math.min(position,arr.length-1));rememberFavorite(arr[position])}const y=scrollY;render();window.scrollTo(0,y);notify(state.fav.includes(id)?'已加入收藏':'已取消收藏')}break;
case'answer':if(q){if(q.t==='multi'){const set=new Set(multiSelections[id]||[]);set.has(b.dataset.letter)?set.delete(b.dataset.letter):set.add(b.dataset.letter);multiSelections[id]=[...set];const y=scrollY;render();window.scrollTo(0,y)}else if(learning==='memorize'&&!examRun){notify('当前是背题模式，切换到练习模式即可作答')}else recordAnswer(q,b.dataset.letter)}break;
case'calc-save':if(q&&examRun)recordAnswer(q,$('#calc-'+id).value.trim()||'已在纸上作答');break;case'multi':if(!multiSelections[id]?.length)notify('请至少选择一个选项');else if(learning==='memorize'&&!examRun)notify('请切换到练习模式再作答');else recordAnswer(q,multiSelections[id].sort().join(''));break;case'blank':{const val=$('#blank-'+id).value.trim();if(!val)notify('请输入答案');else recordAnswer(q,val);break}case'self':recordAnswer(q,b.dataset.value);break;case'reveal':openedAnswers.add(id);render();break;
case'prev':move(-1);break;case'next':move(1);break;case'directory':directory();break;case'card':card();break;case'more':more();break;case'kp':filter='kp:'+b.dataset.value;position=0;limit=20;rememberCurrent();save();close();render();window.scrollTo(0,0);break;
case'jump':position=pool().findIndex(q=>q.q===id);close();move(0);break;case'zoom':zoom(b.dataset.img);break;case'zoom-question':if(q)modal('题干与选项',`<p class="muted small" style="margin-bottom:16px">点击任意图片可进一步放大。</p>${[q.s,...Object.values(q.o||{})].filter(isImage).map((src,i)=>`<div class="panel" style="margin-top:10px;padding:15px"><p class="muted small">${i===0?'题干':'选项 '+String.fromCharCode(64+i)}</p>${content(src,'题图')}</div>`).join('')}`,{image:true});break;
case'zoom-in':case'zoom-out':{zoomScale=Math.max(.5,Math.min(5,zoomScale+(a==='zoom-in'?.5:-.5)));$('#zoom-image').style.width=Number($('#zoom-image').dataset.original)*zoomScale+'px';$('#zoom-label').textContent=zoomScale*100+'%';break}
case'toggle-auto':state.settings.auto=!state.settings.auto;save();b.setAttribute('aria-checked',state.settings.auto);break;
case'exam-tab':examTab=b.dataset.value;render();break;case'exam-subject':initScope(b.dataset.k);examCount=10;examStep=2;render();window.scrollTo(0,0);break;case'exam-step':if(Number(b.dataset.step)===3&&!eligible().length)notify('请先选择题目范围');else{examStep=Number(b.dataset.step);normalizeCount();render()}break;
case'exam-next':examStep=Math.min(3,examStep+1);normalizeCount();render();window.scrollTo(0,0);break;case'exam-prev':examStep=Math.max(1,examStep-1);render();break;case'scope-all':selected=new Set(allQ.filter(q=>q.tk===examSubject).map(q=>q.kpid));document.querySelectorAll('[data-kp]:not(:disabled)').forEach(x=>x.checked=true);updateScope();break;case'scope-none':selected.clear();document.querySelectorAll('[data-kp]').forEach(x=>x.checked=false);updateScope();break;
case'new-exam':examTab='create';examStep=1;render();break;case'start-exam':prepareExam();break;case'confirm-start':startExam();break;case'resume-exam':close();position=0;layout='single';go('exam-run');break;case'finish':finish();break;case'confirm-finish':submitExam();break;case'history-item':showResult(state.history[Number(b.dataset.index)]);break;





case'export':exportBackup();break;case'import':importBackup();break;

}});

document.addEventListener('input',e=>{if(e.target.id==='home-search'){searchTerm=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{$('#course-results').innerHTML=courseResults(searchTerm)},100)}});
document.addEventListener('change',async e=>{const t=e.target;if(t.dataset.kp){t.checked?selected.add(t.dataset.kp):selected.delete(t.dataset.kp);updateScope()}if(t.id==='exam-count')examCount=Number(t.value);if(t.id==='exam-time')examTime=Number(t.value);if(t.id==='pref-layout'){state.settings.layout=t.value;layout=t.value;save();notify('已保存默认显示方式')}if(t.id==='pref-size'){state.settings.size=t.value;save();notify('已调整文字大小')}});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=$('#dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});
addEventListener('hashchange',()=>{clearTimeout(autoTimer);close();render()});
function checkExamClock(){const d=state.draft;if(!d)return;const t=LearningCore.timer(d);if(t.timedOut&&!d.timedOut){d.timedOut=true;d.deadline=t.deadline;save()}document.querySelectorAll('[data-exam-clock]').forEach(el=>{el.textContent=examElapsed();el.classList.toggle('wrong-text',t.timedOut)});if(t.timedOut&&!d.timeNotified&&location.hash==='#exam-run'&&document.visibilityState==='visible'&&!$('#dialog').open){modal('练习时间已到','<p>已记录超时状态并保存答案。你可以提交，也可以继续作答；交卷时会保留实际时长与超时标记。</p><div class="dialog-actions"><button class="btn" data-act="close">继续作答</button><button class="btn primary" data-act="finish">提交练习</button></div>');d.timeNotified=true;save()}}
setInterval(checkExamClock,1000);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')checkExamClock()});


document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();document.querySelector('#main').focus()});

async function showOffline(){return OfflineResources.open()}
let examMode='official',searchReady=false;
function recordAnswer(q,answer){if(learning==='memorize'&&!examRun)return notify('当前是背题模式，切换到练习模式即可作答');const correct=q.t==='calc'?(examRun?null:answer==='ok'):answerCorrect(q.t||'single',answer,q.a);if(examRun){state.draft.answers[q.q]={answer,correct};(state.draft.answerTimes??={})[q.q]=Math.max(Date.now(),(state.draft.answerTimes?.[q.q]||0)+1)}else{learningUI.record(q,correct);learningDirty=true;retrying.delete(q.q);state.rec[q.q]={answer,correct};favoriteMode?rememberFavorite(q):rememberLast(q._key,CHAPTERS[q._key].findIndex(x=>x.q===q.q))}save();const y=scrollY;void render().then(()=>window.scrollTo(0,y));if(state.settings.auto&&correct&&!examRun&&layout==='single'){clearTimeout(autoTimer);autoTimer=setTimeout(()=>{if(location.hash.startsWith('#practice/')||location.hash.startsWith('#favorites/run/'))move(1)},1500)}}
function examHistory(){return state.history.length?state.history.map((x,i)=>`<button class="chapter-row" data-act="history-item" data-index="${i}" style="margin-bottom:12px">${icon('exam')}<span class="chapter-copy"><strong>${META[x.subject].name} · ${x.mode==='official'?'官方模拟':x.mode==='custom'?'专项练习':'历史练习'}</strong><p>${new Date(x.time).toLocaleString('zh-CN')} · ${x.ids.length} 题 · 用时 ${Math.floor((x.elapsedMs||0)/60000)} 分钟${x.timedOut?' · 已超时':''}${x.pending?' · 待自评 '+x.pending+' 题':''}</p></span><span class="chapter-count">${x.score} / ${x.total} 分</span>${icon('chevron')}</button>`).join(''):empty('第一份练习记录，等你完成','提交后的试卷会保留答案，方便随时回看。','创建一次练习','new-exam')}
function officialSpec(){const configs=officialRules;let raw;if(examSubject==='GS')raw=configs.GS;else{const kinds=configs.subjectiveKnowledgePoints.XD,hasBlank=kinds.blank.some(id=>selected.has(id)),hasCalculation=kinds.calculation.some(id=>selected.has(id));raw=configs.XD[hasCalculation?'withBlankAndCalculation':hasBlank?'withBlank':'choiceOnly']}return {...raw,calc:raw.calculation}}
function specText(spec=officialSpec()){return `${spec.choice} 道选择${spec.blank?' + '+spec.blank+' 道填空':''}${spec.calc?' + '+spec.calc+' 道计算':''} = ${spec.total} 题`;}
function initScope(k){examSubject=k;selected=new Set(META[k].chapters.flatMap(c=>c.kps.filter(p=>p.n>0).map(p=>p.id)));}
function validateScope(){if(!selected.size)return'请至少选择一个知识点';if(examMode!=='official')return eligible().length?'':'所选范围没有题目';const spec=officialSpec(),p=eligible(),choice=p.filter(q=>q.t!=='calc'),blank=p.filter(q=>q.t==='calc'&&q.tag==='填空'),calc=p.filter(q=>q.t==='calc'&&q.tag==='计算');if(new Set(choice.map(q=>q.kpid)).size<officialRules.minChoiceKnowledgePoints)return'官网要求至少选择 2 个选择题知识点';if(choice.length<spec.choice)return`选择题不足 ${spec.choice} 道，请扩大范围`;if(blank.length<spec.blank)return`填空题不足 ${spec.blank} 道，请增加填空题章节`;if(calc.length<spec.calc)return`计算题不足 ${spec.calc} 道，请增加计算题章节`;return'';}
function normalizeCount(){if(examMode==='official'){examCount=officialSpec().total;return}const n=eligible().length,allowed=[5,10,20,30,50].filter(x=>x<=n);if(!allowed.includes(examCount))examCount=allowed.find(x=>x>=examCount)||allowed.at(-1)||n;}
function typeName(q){return q.t==='multi'?'多选题':q.t==='calc'?(q.tag==='填空'?'填空题':'计算题'):q.t==='blank'?'填空题':Object.keys(q.o||{}).length===2?'判断题':'单选题';}
function exam(){const official=examMode==='official',spec=officialSpec(),invalid=validateScope(),subjects=official?['GS','XD']:Object.keys(META);return `${heading('练习有范围，复盘有方向',official?'题量与题型按东北大学数学平台在线练习规则生成。':'专项练习可自由设置题量，适合日常巩固。')}<div class="tabs"><button data-act="exam-mode" data-value="official" class="${examTab==='create'&&official?'active':''}">官方模拟</button><button data-act="exam-mode" data-value="custom" class="${examTab==='create'&&!official?'active':''}">专项练习</button><button data-act="exam-tab" data-value="history" class="${examTab==='history'?'active':''}">练习记录 ${state.history.length}</button></div>${examTab==='history'?examHistory():`${state.draft?`<div class="panel between"><div><h3>有一份未完成的练习</h3><p class="muted small">${META[state.draft.subject].name} · 已答 ${Object.values(state.draft.answers).filter(a=>a.answer).length} / ${state.draft.ids.length} 题</p></div><button class="btn soft" data-act="resume-exam">继续 ${icon('arrow')}</button></div>`:''}<div class="stepper" aria-label="创建练习步骤">${[['选择科目',1],['选择范围',2],[official?'确认试卷':'设置题量',3]].map(([n,i])=>`${i>1?'<span class="step-line"></span>':''}<button data-act="exam-step" data-step="${i}" class="${examStep===i?'active':''}" ${examStep===i?'aria-current="step"':''}><span class="circle">${i}</span>${n}</button>`).join('')}</div><div class="exam-layout"><section class="panel">${examStep===1?`<h2>这次想练哪门课？</h2><p class="muted small" style="margin:7px 0 20px">${official?'官网数学模拟支持高数与线代。C 语言、概论可进入专项练习。':'四门课程均可按知识点自由练习。'}</p><div class="course-grid">${subjects.map(k=>`<button class="course-card" data-act="exam-subject" data-k="${k}" style="${examSubject===k?'border-color:var(--blue);background:#f8faff':''}" aria-pressed="${examSubject===k}">${subjectIcon(k)}<h3>${META[k].name}</h3><p class="meta">${nTotal(k).toLocaleString()} 道原题</p>${examSubject===k?icon('check','arrow'):''}</button>`).join('')}</div>`:examStep===2?scopeUI():`<h2>${official?'确认本次模拟卷':'设置专项练习'}</h2>${official?`<div class="official-spec"><span class="pill">题量固定 · 按官网规则</span><h3>${specText(spec)}</h3><p>选择题、填空题每题 4 分；计算题每题 12 分。满分 ${spec.score} 分。</p></div><p class="muted small">题量随所选章节包含的题型自动确定，不能手动修改。所选题目不足时会提示扩大范围。</p>`:`<div class="form-field"><label for="exam-count">题目数量</label><select id="exam-count">${[5,10,20,30,50].filter(n=>n<=eligible().length).concat(eligible().length<5?[eligible().length]:[]).map(n=>`<option value="${n}" ${n===examCount?'selected':''}>${n} 道题</option>`).join('')}</select><p>当前范围有 ${eligible().length} 道题可供抽取。</p></div>`}<div class="form-field"><label for="exam-time">练习计时</label><select id="exam-time">${[[0,'不限时，按自己的节奏'],[15,'15 分钟提醒'],[30,'30 分钟提醒'],[60,'60 分钟提醒']].map(([n,t])=>`<option value="${n}" ${examTime===n?'selected':''}>${t}</option>`).join('')}</select><p>计时是本机练习提醒，时间到达会保留答案。</p></div><div class="inline-note">交卷前不显示答案。填空／计算类主观题交卷后对照解析自评。</div>`}</section><aside class="exam-summary"><div class="panel"><h3>本次${official?'模拟':'练习'}</h3><div class="summary-row"><span>科目</span><strong>${META[examSubject].name}</strong></div><div class="summary-row"><span>已选知识点</span><strong id="selected-count">${selected.size} 个</strong></div><div class="summary-row"><span>范围内题目</span><strong id="eligible-count">${eligible().length} 道</strong></div><div id="official-summary" class="inline-note">${official?specText(spec):'自选题量，随机抽题'}</div><p id="scope-error" class="small wrong-text" role="status">${invalid}</p><div class="exam-sticky-action"><small class="mobile-only" id="mobile-scope-count">${official?`按官网规则 · ${spec.total} 题`:`已选 ${selected.size} 个知识点`}<br>${META[examSubject].name}</small><button class="btn primary" id="exam-next" data-act="${examStep<3?'exam-next':'start-exam'}" ${invalid?'disabled':''}>${examStep<3?'下一步':'开始练习'} ${icon('arrow')}</button></div>${examStep>1?`<button class="btn" data-act="exam-prev">返回上一步</button>`:''}${official?'<button class="text-btn" data-act="official-info">查看题量规则与来源</button>':''}</div></aside></div>`}${footer()}`;}
function scopeUI(){return `<div class="between"><h2>选择练习范围</h2><div class="row"><button class="text-btn" data-act="scope-all">全选</button><button class="text-btn" data-act="scope-none">清空</button></div></div><p class="muted small" style="margin:7px 0 18px">${examMode==='official'?'至少选择 2 个选择题知识点。线代主观题章节单独列在下方。':'展开章节，按知识点勾选。'}</p><div class="scope-list">${META[examSubject].chapters.map((c,i)=>`<details><summary>${icon('chevron')}<span>${esc(c.name)}</span><small>${c.total} 题</small></summary><div class="kp-list"><div class="between"><button class="text-btn" data-act="chapter-select" data-ci="${i}" data-value="on">选中本章</button><button class="text-btn" data-act="chapter-select" data-ci="${i}" data-value="off">取消本章</button></div>${c.kps.map(p=>`<label class="check-row"><input type="checkbox" data-kp="${p.id}" ${selected.has(p.id)?'checked':''} ${!p.n?'disabled':''}><span>${esc(clean(p.name))}</span><small>${p.n} 题</small></label>`).join('')}</div></details>`).join('')}</div>`;}
function updateScope(){normalizeCount();const invalid=validateScope(),spec=officialSpec();$('#selected-count').textContent=selected.size+' 个';$('#eligible-count').textContent=eligible().length+' 道';$('#mobile-scope-count').innerHTML=examMode==='official'?`按官网规则 · ${spec.total} 题<br>${META[examSubject].name}`:`已选 ${selected.size} 个知识点<br>可用 ${eligible().length} 道题`;$('#official-summary').textContent=examMode==='official'?specText(spec):'自选题量，随机抽题';$('#scope-error').textContent=invalid;$('#exam-next').disabled=!!invalid;}
function shuffleCopy(list){const a=list.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function drawGroups(list,n){const groups=new Map();for(const q of list){const g=groups.get(q.kpid)||[];g.push(q);groups.set(q.kpid,g)}const bins=shuffleCopy([...groups.values()]).map(shuffleCopy),out=[];while(out.length<n&&bins.some(g=>g.length)){for(const g of bins){if(out.length>=n)break;if(g.length)out.push(g.pop())}}if(out.length!==n)throw Error('题量不足，无法按指定规则组卷');return out;}
async function startExam(){const err=validateScope();if(err)return notify(err);const button=$('#exam-next');if(button)button.disabled=true;try{const candidates=eligible(),spec=officialSpec();let chosen;if(examMode==='official'){chosen=[...drawGroups(candidates.filter(q=>q.t!=='calc'),spec.choice),...drawGroups(candidates.filter(q=>q.t==='calc'&&q.tag==='填空'),spec.blank),...drawGroups(candidates.filter(q=>q.t==='calc'&&q.tag==='计算'),spec.calc)];}else chosen=shuffleCopy(candidates).slice(0,Math.max(1,Math.min(examCount,candidates.length)));if(examMode==='official'&&(chosen.length!==spec.total||chosen.reduce((n,q)=>n+pointsFor(q),0)!==spec.score))throw Error('官方规则题量或总分校验失败，请联系维护者');await ensureIds(chosen.map(q=>q.q));const draft={id:'E'+Date.now()+'_'+Math.random().toString(36).slice(2,7),subject:examSubject,ids:chosen.map(q=>q.q),answers:{},start:Date.now(),deadline:examTime?Date.now()+examTime*60000:0,minutes:examTime,correct:0,score:0,pending:0,mode:examMode,weights:Object.fromEntries(chosen.map(q=>[q.q,pointsFor(q)])),total:chosen.reduce((n,q)=>n+pointsFor(q),0)};localStorage.setItem('NEU-DRAFT:'+_ukey,JSON.stringify(toCoreExam(draft,false)));state.draft=draft;learningData.drafts[draft.id]=toCoreExam(draft,false);saveLocal();scheduleSync();baselineDraft=JSON.stringify(draft);save();close();position=0;layout='single';learning='practice';go('exam-run')}catch(e){notify(e.message||'组卷失败，请稍后重试')}finally{if(button?.isConnected)button.disabled=false}}
function prepareExam(){const err=validateScope();if(err)return notify(err);if(state.draft){modal('保留还是替换已有草稿？','<p>开始新练习后，原草稿仍可在“我的 → 未完成试卷”中继续。已交试卷和日常学习记录会保留。</p><div class="dialog-actions"><button class="btn" data-act="resume-exam">继续原练习</button><button class="btn primary" data-act="confirm-start">开始新练习</button></div>');return}void startExam();}
function submitExam(){const d=state.draft;if(!d)return;const timing=LearningCore.timer(d);const entry={...d,timedOut:timing.timedOut,deadline:timing.deadline,endedAt:Date.now(),elapsedMs:timing.elapsed,time:d.start,updatedAt:Date.now(),correct:0,score:0,pending:0};for(const id of entry.ids){const q=byId.get(id),a=entry.answers[id];if(q?.t==='calc'){if(a?.correct===null||!a){entry.pending++;continue}}if(a?.correct){entry.correct++;entry.score+=(entry.weights[id]||4)}}const core=toCoreExam(entry,true),next=mergeExams(exams,[core]);try{const before=snapshot();const nextData=LearningCore.clean(learningData);nextData.drafts[d.id]={...core,closed:true};for(const id of entry.ids){const a=entry.answers[id];if(a&&typeof a.correct==='boolean')nextData.events['exam_'+entry.id+'_'+id]={kind:'answer',qid:id,correct:a.correct,t:entry.endedAt,source:'exam',review:false};}localStorage.setItem('NEU-STATE:'+_ukey,JSON.stringify({...before,...nextData,exams:next}));learningData=nextData;exams=next;saveLocal();scheduleSync();localStorage.removeItem('NEU-DRAFT:'+_ukey);state.draft=null;baselineDraft='null';hydrate();close();examTab='history';go('exam');setTimeout(()=>void showResult(historyToUI(core)),0)}catch(e){notify('试卷保存失败，草稿已保留，请勿关闭页面并导出备份')}}
async function showResult(x){if(!x)return;try{await ensureIds(x.ids)}catch(e){notify('部分题目未能加载，试卷记录仍保留')}const pending=x.ids.filter(id=>byId.get(id)?.t==='calc'&&(!x.answers[id]||x.answers[id].correct===null)).length;modal('练习结果',`<div class="results-score"><strong>${Number(x.score)||0}<small class="muted" style="font-size:22px"> / ${Number(x.total)||0}</small></strong><p>${META[x.subject].name} · 答对 ${x.correct} / ${x.ids.length} 题${pending?' · 待自评 '+pending+' 题':''}</p></div><p class="inline-note">用时 ${Math.floor((x.elapsedMs||0)/60000)} 分 ${Math.floor((x.elapsedMs||0)/1000)%60} 秒${x.timedOut?' · 已超时':' · '+(x.minutes?'限时内提交':'不限时')}。</p><p class="muted small">点击题目回看答案。主观题按参考解答自评，模拟记录单独保存。</p><div class="chapter-list" style="margin-top:16px">${x.ids.map((id,i)=>{const q=byId.get(id),a=x.answers[id];return `<button class="chapter-row" data-act="history-question" data-id="${esc(id)}" data-history="${esc(x.id)}" ${!q?'disabled':''}><span class="chapter-copy"><strong>第 ${i+1} 题 · ${q?esc(clean(q.kp)):'题号暂未匹配'}</strong><p>${q?.t==='calc'?'主观题 · '+(x.weights[id]||4)+' 分':a?'你的答案：'+esc(a.answer)+' · 参考答案：'+esc(q?.a||''):'未作答'}</p></span><span class="${a?.correct?'correct-text':'wrong-text'} small">${a?.correct?'正确':q?.t==='calc'&&(!a||a.correct===null)?'待自评':a?'待复习':'未做'}</span></button>`}).join('')}</div>`);}
async function showHistoryQuestion(id,historyId){const entry=state.history.find(x=>x.id===historyId),q=byId.get(id);if(!entry||!q)return notify('此题暂时无法匹配，原记录已保留');try{await ensureIds([id]);const r=entry.answers[id];modal('原题回看',`<div class="inline-note">${META[q.tk].name} · ${esc(clean(q.kp))}<br>${q.t==='calc'?'请对照解析自评':'当时答案：'+esc(r?.answer||'未作答')+' · 参考答案：'+esc(q.a)}</div>${q.t==='calc'&&r?.answer?`<p class="muted small">作答记录：${esc(r.answer)}</p>`:''}<div class="stem">${content(q.s,'题干',q.t==='calc')}</div><div class="stack">${Object.entries(q.o||{}).map(([n,v])=>`<div class="row"><strong>${String.fromCharCode(64+Number(n))}</strong>${content(v,'选项')}</div>`).join('')}</div><div class="answer-result"><strong>解析</strong>${q.eh?safeHTML(q.eh):q.et?esc(q.et):q.w?content(q.w,'解析'):'原题未提供详细解析。'}</div>${q.t==='calc'?`<div class="dialog-actions"><button class="btn" data-act="history-self" data-id="${id}" data-history="${entry.id}" data-value="no">还需练习 · 0 分</button><button class="btn primary" data-act="history-self" data-id="${id}" data-history="${entry.id}" data-value="ok">已掌握 · ${entry.weights[id]||4} 分</button></div>`:''}`)}catch(e){notify(e.message)}}
function baseMe(){const lastSync=_read('NEU-LAST-SYNC:'+_ukey,0),cached=currentSession.user?.id!==LOCAL_UID;return `${heading('我的学习空间','账号、备份与习惯，在这里统一管理。')}<div class="settings-grid"><div class="stack"><section class="panel"><div class="profile-head"><div class="avatar">${icon('user')}</div><div><h2>${state.login?'已登录':cached?'已保留登录':'本机学习者'}</h2><p class="muted small">${esc(currentSession.user?.email||'本机学习记录随时可用')}</p></div></div><div class="setting-row">${icon('shield')}<div class="setting-copy"><strong>${state.login?'自动登录已开启':'首次登录后自动保持登录'}</strong><p>${cached?'网络暂不可用时仍可继续本机练习':'使用学习记录同步账号，不是学校数学平台账号'}</p></div><button class="text-btn" data-act="login">${cached?'账号设置':'登录'}</button></div><div class="setting-row">${icon('cloud')}<div class="setting-copy"><strong data-sync-label>${esc(syncLabel)}</strong><p>${lastSync?'上次成功同步：'+new Date(Number(lastSync)).toLocaleString('zh-CN'):'先保存在本机，联网并登录后自动同步'}</p></div><button class="text-btn" data-act="sync-now">同步</button></div></section><section class="panel"><h3>数据与备份</h3><div class="setting-row">${icon('download')}<div class="setting-copy"><strong>学习记录备份</strong><p>${state.backupAt?'上次导出：'+new Date(state.backupAt).toLocaleString('zh-CN'):'导出作答、收藏和已交试卷，方便迁移'}</p></div></div><div class="backup-actions"><button class="btn soft" data-act="export">${icon('download')}导出学习记录</button><button class="btn" data-act="import">${icon('upload')}导入备份</button></div><div class="setting-row">${icon('wifi')}<div class="setting-copy"><strong>离线资源</strong><p>${window.AndroidBackup?'APK 已内置完整题库':'按科目下载，断网也能继续练习'}</p></div><button class="text-btn" data-act="offline">管理</button></div><div class="setting-row">${icon('refresh')}<div class="setting-copy"><strong>旧版迁移与恢复</strong><p>合并本机旧记录，或恢复导入前备份</p></div><button class="text-btn" data-act="migration">查看</button></div></section></div><div class="stack"><section class="panel"><h3>练习偏好</h3><div class="setting-row">${icon('list')}<div class="setting-copy"><strong>默认显示方式</strong><p>单题专注作答，列表连续浏览</p></div><select id="pref-layout" aria-label="默认显示方式"><option value="single" ${state.settings.layout==='single'?'selected':''}>单题模式</option><option value="list" ${state.settings.layout==='list'?'selected':''}>列表模式</option></select></div><div class="setting-row">${icon('settings')}<div class="setting-copy"><strong>文字大小</strong><p>图片题干可单独点击放大</p></div><select id="pref-size" aria-label="文字大小"><option value="standard" ${state.settings.size==='standard'?'selected':''}>标准</option><option value="large" ${state.settings.size==='large'?'selected':''}>大字</option></select></div><div class="setting-row">${icon('arrow')}<div class="setting-copy"><strong>答对后自动下一题</strong><p>开启后停留 1.5 秒再跳转</p></div><button class="switch" role="switch" aria-label="答对后自动下一题" aria-checked="${state.settings.auto}" data-act="toggle-auto"></button></div></section><section class="panel"><h3>关于题库</h3><p class="muted small" style="margin-top:12px;line-height:1.9">4 门课程 · 47 个章节 · 7,397 道题<br>高等数学、线性代数、C 语言与概论。</p><button class="text-btn" data-act="about">使用说明 ${icon('arrow')}</button><div class="setting-row"><div class="setting-copy"><strong>版本 ${window.MB_VER}</strong><p>更新会保留学习记录与收藏</p></div><button class="text-btn" data-act="check-update">检查更新</button></div></section></div></div>${footer()}`;}
function about(){modal('关于大学题库',`<p>题库包含 4 门课程、47 个章节、7,397 道题。练习记录先保存在本机，首次登录后自动保持会话并同步。</p><div class="inline-note">官方模拟的题量与题型已按 mathe.neu.edu.cn 在线练习核验；专项练习可自选题量。</div><p class="muted small">题目内容沿用原始题库。图片题干可点击放大；搜索支持章节、知识点和文字题，暂不识别图片内文字。</p><p class="muted small">请定期导出学习记录。浏览器可在“我的 → 离线资源”下载题库，新版 APK 已内置完整资源。</p><div class="dialog-actions"><button class="btn primary" data-act="close">知道了</button></div>`)}
