async function enterChapter(key,index=null){try{if(!CHAPTERS[key])return;index=index==null?chapterResumeIndex(key):Math.max(0,Math.min(CHAPTERS[key].length-1,index));chapterEntry={key,index};previousRoute=location.hash.slice(1)||'home';chapterKey=key;position=index;filter='all';limit=Math.max(20,Math.ceil((index+1)/20)*20);examRun=false;rememberLast(key,index);save();go('practice/'+key)}catch(e){notify(e.message)}}
async function openQuestion(id){if(favoriteMode&&favoriteBase().some(q=>q.q===id)){let at=pool().findIndex(q=>q.q===id);if(at<0){filter='all';at=pool().findIndex(q=>q.q===id)}position=at;limit=Math.max(limit,Math.ceil((at+1)/20)*20);rememberFavorite(byId.get(id));await render();return}const q=byId.get(id);if(!q)return notify('该题编号暂未匹配，原记录会保留');return enterChapter(q._key,CHAPTERS[q._key].findIndex(x=>x.q===id));}
async function render(){const ticket=++renderSequence;let r=location.hash.slice(1)||'home';favoriteMode=r.startsWith('favorites/run/');const isPractice=favoriteMode||r.startsWith('practice/')||r==='exam-run',routeChanged=r!==activeRoute;activeRoute=r;
 try{const needs=[];if(favoriteMode){if(routeChanged)enterFavoriteScope(r);examRun=false;needs.push(...pool().slice(0,layout==='list'?limit:position+1).map(q=>q.q));}else if(r.startsWith('practice/')){const key=r.slice(9);if(!CHAPTERS[key])throw Error('章节地址无效，请从题库重新进入');if(chapterKey!==key||routeChanged){chapterKey=key;position=chapterEntry?.key===key?chapterEntry.index:chapterResumeIndex(key);chapterEntry=null;filter='all';limit=Math.max(20,Math.ceil((position+1)/20)*20)}needs.push(...CHAPTERS[key].map(q=>q.q));examRun=false;}else if(r==='exam-run'){if(!state.draft){go('exam');return}if(state.draft.ids.some(id=>!byId.has(id)))throw Error('草稿存在无法匹配的题目，已保留原记录，请导出备份后检查');needs.push(...state.draft.ids);examRun=true;chapterKey=byId.get(state.draft.ids[0])._key;}else{examRun=false;if(r==='review')needs.push(...(reviewTab==='wrong'?wrongIds():state.fav).filter(id=>byId.has(id)).slice(0,reviewLimit));}
 if(r==='review'){needs.length=0;needs.push(...(reviewTab==='wrong'?wrongIds():state.fav).filter(id=>byId.has(id)&&(reviewSubject==='all'||byId.get(id).tk===reviewSubject)).slice(0,reviewLimit));}
 if(needs.some(id=>!loadedChapters.has(byId.get(id)?._key))){$('#main').innerHTML='<div class="panel loading-panel" role="status">正在读取题目…</div>';await ensureIds(needs);if(ticket!==renderSequence)return;}
 document.body.classList.toggle('practice-mode',isPractice);document.body.classList.toggle('list-mode',isPractice&&layout==='list');document.body.classList.toggle('exam-mode',r==='exam'&&examTab==='create');nav();let html='',title='题库';if(isPractice){html=practice();title=examRun?'模拟作答':favoriteMode?'收藏练习':'章节练习'}else if(r==='favorites'||r.startsWith('favorites/course/')){html=favoriteCatalogue(r.split('/')[2]||'');title='我的收藏'}else if(r.startsWith('course/')){const k=r.split('/')[1];html=course(k);title=META[k]?.name||'题库'}else if(r==='review'){html=review();title='复习';const unmatched=state.fav.filter(id=>!byId.has(id)).length;if(unmatched&&reviewTab==='fav')html='<div class="inline-note">有 '+unmatched+' 条旧收藏暂时无法匹配题目，编号已保留在备份中。</div>'+html;}else if(r==='exam'||r.startsWith('paper/')){if(r.startsWith('paper/'))examTab='history';html=exam();title='模拟练习'}else if(r==='smart-review'){html=learningUI.reviewPage();title='智能复习'}else if(r==='analytics'){html=learningUI.analytics();title='学习分析'}else if(r==='search'){html=learningUI.searchPage();title='题库搜索'}else if(r==='admin'){html=await adminPage();title='用户管理'}else if(r==='me'){html=me();title='我的'}else html=home();
 $('#top-left').innerHTML=isPractice?`<div class="top-title"><button class="icon-btn" data-act="back-practice" aria-label="返回">${icon('back')}</button><strong>${examRun?'模拟作答':META[chapterKey.split('_')[0]].name}</strong><small> / ${examRun?'作答中':favoriteMode?'收藏练习':'章节练习'}</small></div>`:r.startsWith('course/')?`<div class="top-title"><a class="icon-btn" href="#home" aria-label="返回题库">${icon('back')}</a><strong>${title}</strong></div>`:`<div class="breadcrumb"><span class="desktop-only">我的学习空间</span><span class="desktop-only">/</span><strong>${title}</strong></div>`;
 if(ticket!==renderSequence)return;$('#main').innerHTML=html;updateStatus();studyObserver.disconnect();for(const el of document.querySelectorAll('.topbar,.practice-controls'))studyObserver.observe(el);updatePracticeOffsets();typeset($('#main'));if(r==='search'&&routeChanged)void learningUI.loadSearch();if(r==='exam-run')checkExamClock();if(r.startsWith('paper/')&&routeChanged){const x=state.history.find(e=>e.id===decodeURIComponent(r.slice(6)));if(x)await showResult(x);else notify('未找到这份试卷，请确认登录账号')}if(isPractice&&layout==='list'&&routeChanged&&pool()[position])$('#q-'+pool()[position].q)?.scrollIntoView({block:'start'});
 }catch(e){if(ticket!==renderSequence)return;$('#main').innerHTML=`<section class="empty"><h3>暂时无法打开</h3><p>${esc(e.message)}。学习记录仍保留。</p><button class="btn primary" data-act="retry-view">重试</button> <a class="btn" href="#home">返回题库</a></section>`;nav();}}
