function accountError(e){const m=String(e?.message||'');if(/invalid login/i.test(m))return'邮箱或密码不正确';if(/email not confirmed/i.test(m))return'请先验证邮箱，可使用“重发验证邮件”';if(/rate|too many|seconds/i.test(m))return'操作较频繁，请稍后再试';if(/not allowed|smtp|sending.*email/i.test(m))return'邮件暂时无法发送，请联系管理员检查邮件服务';if(/fetch|network|timeout/i.test(m))return'网络连接失败，请稍后重试';return m||'操作未完成，请稍后重试'}
function authForm(mode='login',email=''){
 const change=mode==='password',login=mode==='login',signup=mode==='signup',recovery=mode==='recovery',password=login||signup||change||recovery;
 const title={login:'登录同步账号',signup:'注册账号',forgot:'找回密码',resend:'重发验证邮件',password:'修改密码',recovery:'设置新密码'}[mode];
 modal(title,`<p class="muted small">${signup?'注册后请到邮箱验证，再登录即可自动保存会话。':login?'使用题库同步邮箱账号，首次登录后自动保持登录。':change?'输入当前密码，再设置新密码。':recovery?'验证已通过，请设置新密码。':'填写注册邮箱，我们会发送后续操作邮件。'}</p><form id="account-form" data-mode="${mode}">${!change&&!recovery?`<div class="form-field"><label for="login-email">邮箱</label><input id="login-email" type="email" autocomplete="username" maxlength="254" required value="${esc(email||currentSession.user?.email||'')}"></div>`:''}${change?'<div class="form-field"><label for="current-password">当前密码</label><input id="current-password" type="password" autocomplete="current-password" required></div>':''}${password?`<div class="form-field"><label for="login-password">${login?'密码':'新密码'}</label><input id="login-password" type="password" autocomplete="${login?'current-password':'new-password'}" ${login?'':'minlength="8"'} maxlength="128" required></div>`:''}${signup||change||recovery?'<div class="form-field"><label for="confirm-password">确认密码</label><input id="confirm-password" type="password" autocomplete="new-password" minlength="8" maxlength="128" required><p>至少 8 位，建议混合字母、数字和符号。</p></div>':''}<p id="account-message" role="status" aria-live="polite" class="small"></p><div class="dialog-actions"><button class="btn primary" type="submit">${{login:'登录并自动同步',signup:'注册并发送验证邮件',forgot:'发送重置邮件',resend:'发送验证邮件',password:'保存新密码',recovery:'保存新密码'}[mode]}</button></div></form><div class="account-links">${login?'<button class="text-btn" data-account="signup">注册新账号</button><button class="text-btn" data-account="forgot">忘记密码</button><button class="text-btn" data-account="resend">重发验证邮件</button>':!change&&!recovery?'<button class="text-btn" data-account="login">返回登录</button>':''}${login&&currentSession.user?.id!==LOCAL_UID?'<button class="text-btn" data-act="logout-confirm">退出当前账号</button>':''}</div>`);
}
