async function acceptAccountSession(session){if(!session?.user)throw Error('未获得有效登录会话');save();currentSession={user:{id:session.user.id,email:session.user.email}};localStorage.setItem('mb_last_user',JSON.stringify(currentSession.user));CLOUD_DOWN=false;loadForUser(currentSession);hydrate();layout=state.settings.layout;try{await refreshAccountRole()}catch{accountRole={uid:'',admin:false,allowed:true}}}
document.addEventListener('submit',async e=>{
 if(e.target.id!=='account-form')return;e.preventDefault();if(accountBusy)return;
 const form=e.target,mode=form.dataset.mode,message=form.querySelector('#account-message'),button=form.querySelector('[type=submit]'),email=form.querySelector('#login-email')?.value.trim(),password=form.querySelector('#login-password')?.value;
 if(form.querySelector('#confirm-password')?.value!==password&&['signup','password','recovery'].includes(mode)){message.textContent='两次输入的密码不一致';return}
 accountBusy=true;button.disabled=true;message.textContent='正在处理…';
 try{
  const auth=initCloud().auth;let result;
  if(mode==='login'){result=await auth.signInWithPassword({email,password});if(result.error)throw result.error;await acceptAccountSession(result.data.session);close();await render();await synchronize();notify('登录成功，之后将自动保持登录');}
  else if(mode==='signup'){result=await auth.signUp({email,password,options:{emailRedirectTo:ACCOUNT_RETURN+'verified'}});if(result.error)throw result.error;if(result.data.session){await acceptAccountSession(result.data.session);close();await render();notify('注册成功，已登录')}else{form.reset();message.textContent='如该邮箱可以注册，验证邮件将发送至邮箱。请检查收件箱和垃圾邮件；已注册用户可直接登录或找回密码。';}}
  else if(mode==='forgot'||mode==='resend'){result=mode==='forgot'?await auth.resetPasswordForEmail(email,{redirectTo:ACCOUNT_RETURN+'recovery'}):await auth.resend({type:'signup',email,options:{emailRedirectTo:ACCOUNT_RETURN+'verified'}});if(result.error)throw result.error;message.textContent='如该邮箱符合条件，邮件将发送至邮箱。请按邮件提示操作。';}
  else {if(mode==='password'){const uid=currentSession.user?.id;result=await auth.signInWithPassword({email:currentSession.user.email,password:form.querySelector('#current-password').value});if(result.error)throw result.error;if(result.data.user?.id!==uid)throw Error('账号已变化，请重新登录');}result=await auth.updateUser({password});if(result.error)throw result.error;sessionStorage.removeItem('mb-password-recovery');close();notify('密码已更新');await render();}
 }catch(err){message.textContent=accountError(err);message.classList.add('wrong-text')}finally{accountBusy=false;if(button.isConnected)button.disabled=false;}
});
