async function accountCallback(){
 const url=new URL(location.href),hash=new URLSearchParams(url.hash.slice(1)),kind=url.searchParams.get('account'),isCallback=hash.has('access_token')||hash.has('error_description')||url.searchParams.has('code');
 if(!isCallback)return false;
 const recovery=hash.get('type')==='recovery'||kind==='recovery',error=hash.get('error_description');
 const access=hash.get('access_token'),refresh=hash.get('refresh_token'),code=url.searchParams.get('code');
 history.replaceState(null,'',url.pathname+'#me');
 try{if(error)throw Error('验证链接无效或已过期，请重新发送邮件');let result;if(code)result=await initCloud().auth.exchangeCodeForSession(code);else if(access&&refresh)result=await initCloud().auth.setSession({access_token:access,refresh_token:refresh});else throw Error('验证链接不完整，请重新发送邮件');if(result.error)throw result.error;await acceptAccountSession(result.data.session);if(recovery)sessionStorage.setItem('mb-password-recovery',currentSession.user.id);return recovery;}catch(e){setTimeout(()=>notify(accountError(e)),500);return false;}
}
